-- chair-step: inverse of read_lane_v2_b2_36_agent_term_list — un-enrolls agent.term_list from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'agent' and table_name = 'term_list' and is_active);
select iam.apply_rls('agent', 'term_list', (select token from platform.entity_types where schema_name = 'agent' and table_name = 'term_list' and is_active), (select rls_variant from platform.entity_types where schema_name = 'agent' and table_name = 'term_list' and is_active));
